func TestUnitServiceNetworkingConnection_isProducerServicesInUseError(t *testing.T) {
	t.Parallel()

	producerErr := &tpgresource.CommonOpError{
		Status: &cloudresourcemanager.Status{
			Code:    int64(codes.FailedPrecondition),
			Message: "Failed to delete connection; Producer services (e.g. CloudSQL, Cloud Memstore, etc.) are still using this connection.",
		},
	}

	cases := map[string]struct {
		err  error
		want bool
	}{
		"producer services still hold the connection": {
			err:  producerErr,
			want: true,
		},
		"wrapped by the operation waiter": {
			// OperationWait wraps the operation error before the delete function
			// sees it, so the match has to survive unwrapping.
			err:  fmt.Errorf("Error waiting for Delete Service Networking Connection: %w", producerErr),
			want: true,
		},
		"failed precondition for an unrelated reason": {
			err: &tpgresource.CommonOpError{
				Status: &cloudresourcemanager.Status{
					Code:    int64(codes.FailedPrecondition),
					Message: "Failed to delete connection; the connection does not exist.",
				},
			},
			want: false,
		},
		"matching message under a different status code": {
			err: &tpgresource.CommonOpError{
				Status: &cloudresourcemanager.Status{
					Code:    int64(codes.PermissionDenied),
					Message: "Producer services are still using this connection",
				},
			},
			want: false,
		},
		"unrelated error type": {
			err:  fmt.Errorf("connection reset by peer"),
			want: false,
		},
		"nil error": {
			err:  nil,
			want: false,
		},
	}

	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			if got := isProducerServicesInUseError(tc.err); got != tc.want {
				t.Errorf("isProducerServicesInUseError() = %t, want %t", got, tc.want)
			}
		})
	}
}
